// Aggregate data from all inputs
const todayLeads = $input.first().json;
const todayOrders = $input.all()[1]?.json || [];
const allLeads = $input.all()[2]?.json || [];

// Calculate metrics
const totalLeads = allLeads.length;
const todayLeadsCount = Array.isArray(todayLeads) ? todayLeads.length : 0;
const todayOrdersCount = Array.isArray(todayOrders) ? todayOrders.length : 0;

// Calculate revenue
const todayRevenue = todayOrders.reduce((sum, order) => {
  return sum + (parseFloat(order.Amount) || 0);
}, 0);

// Lead source breakdown for today
const leadsBySource = {};
if (Array.isArray(todayLeads)) {
  todayLeads.forEach(lead => {
    const source = lead.Source || 'unknown';
    leadsBySource[source] = (leadsBySource[source] || 0) + 1;
  });
}

// Lead status breakdown
const leadsByStatus = {
  hot: 0,
  warm: 0,
  cold: 0,
  customer: 0
};

if (Array.isArray(allLeads)) {
  allLeads.forEach(lead => {
    const status = lead.Status?.toLowerCase() || 'cold';
    if (leadsByStatus.hasOwnProperty(status)) {
      leadsByStatus[status]++;
    }
  });
}

// Calculate conversion rate
const conversionRate = totalLeads > 0 
  ? ((leadsByStatus.customer / totalLeads) * 100).toFixed(2)
  : 0;

// Average order value
const avgOrderValue = todayOrdersCount > 0
  ? (todayRevenue / todayOrdersCount).toFixed(2)
  : 0;

return {
  json: {
    date: new Date().toISOString().split('T')[0],
    metrics: {
      total_leads: totalLeads,
      today_leads: todayLeadsCount,
      today_orders: todayOrdersCount,
      today_revenue: todayRevenue.toFixed(2),
      avg_order_value: avgOrderValue,
      conversion_rate: conversionRate
    },
    leadsBySource,
    leadsByStatus,
    topSources: Object.entries(leadsBySource)
      .sort((a, b) => b[1] - a[1])
      .slice(0, 3)
      .map(([source, count]) => `${source}: ${count}`)
      .join(', ')
  }
};

